messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
Here is the single, self-contained HTML file.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Three.js Racing Loop</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>

<!-- Import Map to handle the module dependency cleanly -->
<script type="importmap">
    {
        "imports": {
            "three": "./three.module.js"
        }
    }
</script>

<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const TRACK_LENGTH = 100;
    const START_Z = -50;
    const FINISH_Z = 50;
    const LANE_LEFT_X = -3;
    const LANE_RIGHT_X = 3;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 20, 90);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(10, 20, 0);
    dirLight.castShadow = true;
    dirLight.shadow.camera.left = -20;
    dirLight.shadow.camera.right = 20;
    dirLight.shadow.camera.top = 20;
    dirLight.shadow.camera.bottom = -20;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    scene.add(dirLight);

    // --- Environment (Ground & Track) ---
    // Ground
    const groundGeo = new THREE.PlaneGeometry(200, 200);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a5f0b });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    // Track
    const trackGeo = new THREE.PlaneGeometry(10, TRACK_LENGTH);
    const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const track = new THREE.Mesh(trackGeo, trackMat);
    track.rotation.x = -Math.PI / 2;
    track.position.y = 0;
    track.receiveShadow = true;
    scene.add(track);

    // Finish Line
    const finishGeo = new THREE.PlaneGeometry(10, 1);
    const finishMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.set(0, 0.02, FINISH_Z);
    scene.add(finishLine);

    // --- Car Creation ---
    function createCar(colorHex) {
        const carGroup = new THREE.Group();

        // Body
        const bodyGeo = new THREE.BoxGeometry(2, 1, 4);
        const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.3, metalness: 0.4 });
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.position.y = 0.7;
        body.castShadow = true;
        carGroup.add(body);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(1.6, 0.8, 2);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.y = 1.4;
        cabin.position.z = -0.5;
        cabin.castShadow = true;
        carGroup.add(cabin);

        // Wheels
        const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

        const positions = [
            [-1.1, 0.4, 1.2], [1.1, 0.4, 1.2],
            [-1.1, 0.4, -1.2], [1.1, 0.4, -1.2]
        ];

        positions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.rotation.z = Math.PI / 2;
            wheel.position.set(...pos);
            wheel.castShadow = true;
            carGroup.add(wheel);
        });

        return carGroup;
    }

    const redCar = createCar(0xff0000);
    redCar.position.set(LANE_LEFT_X, 0, START_Z);
    scene.add(redCar);

    const blueCar = createCar(0x0055ff);
    blueCar.position.set(LANE_RIGHT_X, 0, START_Z);
    scene.add(blueCar);

    // --- Logic & Animation State ---
    let startTime = 0;
    const RACE_DURATION = 6; // Seconds for one full loop

    // Spline for the Red Car's curve (Blue leads -> Red overtakes)
    // Points: Start, Mid (Blue ahead), End (Red ahead)
    const redCurvePoints = [
        new THREE.Vector3(LANE_LEFT_X, 0, START_Z),
        new THREE.Vector3(LANE_LEFT_X, 0, 0),      // Middle
        new THREE.Vector3(LANE_LEFT_X, 0, FINISH_Z) // Finish
    ];
    // Normalize to local space for curve
    redCurvePoints.forEach(p => p.sub(new THREE.Vector3(LANE_LEFT_X, 0, START_Z)););
    const redCurve = new THREE.CatmullRomCurve3(redCurvePoints, false, 'centripetal');

    function animate() {
        requestAnimationFrame(animate);

        const now = performance.now();
        const elapsed = (now - startTime) / 1000; // seconds

        // Loop logic
        if (elapsed > RACE_DURATION) {
            startTime = now;
        }
        const t = (now - startTime) / 1000;

        // --- Blue Car Logic (Straight, slower) ---
        // Blue runs at constant speed. 
        // Total distance = TRACK_LENGTH. 
        // To make Red win, Blue finishes later.
        const blueSpeed = TRACK_LENGTH / (RACE_DURATION - 0.5); // Blue arrives at ~5.5s
        blueCar.position.z = START_Z + (t * blueSpeed);

        // --- Red Car Logic (Curve, accelerates) ---
        // We use the curve for X offset (overtaking) and time for Z speed.
        // Red needs to cross finish line around 5.0s.
        const redFinishTime = 5.0;
        const redZProgress = Math.min(t / redFinishTime, 1.0);

        // Acceleration logic: cubic ease-out to start slower, speed up
        // t=0 -> 0, t=1 -> 1
        const redZ = START_Z + (t * blueSpeed * 1.1) * (1 - Math.pow(1 - redZProgress, 2));

        // Get X from curve based on how far they are along the track
        // The curve is defined from 0 to 1 based on Z distance.
        const curveT = (redZ - START_Z) / TRACK_LENGTH;
        const curvePoint = redCurve.getPointAt(Math.max(0, Math.min(1, curveT)));

        redCar.position.x = curvePoint.x;
        redCar.position.z = redZ;

        // --- Camera Tracking ---
        // Camera follows the midpoint between cars, looking ahead
        const midZ = (redCar.position.z + blueCar.position.z) / 2;
        const midX = (redCar.position.x + blueCar.position.x) / 2;

        // Smooth camera movement
        camera.position.x += (midX - camera.position.x) * 0.05;
        camera.position.z += (midZ + 15 - camera.position.z) * 0.05; // 15 units behind lead car
        camera.position.y = 8;
        camera.lookAt(midX, 0, midZ + 10);

        renderer.render(scene, camera);
    }

    // Handle resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start
    startTime = performance.now();
    animate();

</script>
</body>
</html>
```
